// Re-export DerivedFact-related types used by derivation compilers
// (already imported via crate::types::*)

// -- Core Functional Types ------------------------------------------

// -- Core Functional Types ------------------------------------------
//
// Constraints, derivations, and state machines compile to Func AST nodes.
// Evaluation is beta reduction: apply(func, object, defs) -> object.
//
// All constraints compile to AST (Func) nodes:
//   Pure AST:       IR (fully pure -- Filter + Eq + Construction, zero closures)
//   AST + Native:   UC, MC, FC, VC, AS, SY, AT, IT, TR, AC, RF,
//                   XO, XC, OR, SS, EQ, forbidden, obligatory
//                   (extract_facts_func for fact extraction,
//                   Native kernel for constraint-specific logic)
//   Constant:       Permitted (Func::constant(phi))
//   Goal:           all constraints as pure Func (Condition, Filter, Compose, etc.)


#[derive(Clone, Debug)]
pub(crate) enum Modality {
    Alethic,
    Deontic(DeonticOp),
}

#[derive(Clone, Debug)]
pub(crate) enum DeonticOp {
    Forbidden,
    Obligatory,
    Permitted,
}

/// A compiled constraint. Evaluation is apply(func, eval_context_object) -> violations.
/// text/modality retained for introspection (used by explain, verify).
#[allow(dead_code)]
pub(crate) struct CompiledConstraint {
    pub(crate) id: String,
    pub(crate) text: String,
    pub(crate) modality: Modality,
    pub(crate) func: crate::ast::Func,
}


/// A compiled derivation rule. Evaluation is apply(func, population_object) -> derived facts.
/// text/kind retained for introspection and rule classification.
#[allow(dead_code)]
pub(crate) struct CompiledDerivation {
    pub(crate) id: String,
    pub(crate) text: String,
    pub(crate) kind: DerivationKind,
    pub(crate) func: crate::ast::Func,
    /// task-814-stratify-3plus: the literal cell id the consequent
    /// emits into (when `consequent_cell` is `Literal(..)`). Empty
    /// for dynamic consequent shapes (`AntecedentRole`, aggregates
    /// resolved at evaluation time). Used by
    /// `evaluate::forward_chain_stratified` to build the dependency
    /// graph between rules at runtime so 3+-level priority cascades
    /// can stratify topologically rather than collapsing into a
    /// single stratum-2 round.
    pub(crate) consequent_cell: String,
    /// task-930: materialization policy carried from DerivationRuleDef
    /// through compile to the def-emission step. Stored rules emit
    /// `derivation:{id}` def cells (forward chain materializes them);
    /// View rules skip emission and are computed lazily on read.
    pub(crate) materialization: crate::types::MaterializationPolicy,
}

impl Default for CompiledDerivation {
    fn default() -> Self {
        Self {
            id: String::new(),
            text: String::new(),
            kind: DerivationKind::ModusPonens,
            func: crate::ast::Func::constant(crate::ast::Object::phi()),
            consequent_cell: String::new(),
            materialization: crate::types::MaterializationPolicy::Stored,
        }
    }
}

/// task-814-stratify-3plus: extract the dependency-graph metadata
/// (consequent cell + role literals + negation-read cells) from a
/// `DerivationRuleDef`. Used at every `CompiledDerivation` construction
/// site so the runtime forward chainer can topologically stratify rules
/// that participate in a 3+-level priority cascade.
///
/// `consequent_cell` is the `Literal(..)` cell id, or empty for dynamic
/// shapes. `consequent_role_literals` is the (role, value) pin set
/// authored on the consequent. `negation_reads` enumerates each
/// `AbsenceOf` antecedent paired with that antecedent's role-literal
/// pins (extracted from `antecedent_role_literals` at the matching
/// antecedent index). The pin pairing is what lets the chainer
/// distinguish "rule A's consequent could satisfy rule B's AbsenceOf"
/// (creates a dependency edge) from "rule A writes the same cell but
/// with a non-overlapping role literal" (no edge — three rules all
/// writing 'Task_has_Target_Posture' with different literals don't
/// form a dependency cycle).
fn derivation_dep_metadata(rule: &crate::types::DerivationRuleDef) -> (
    String,
    Vec<(String, String)>,
    Vec<(String, Vec<(String, String)>)>,
) {
    let consequent_cell = rule.consequent_cell.literal_id().to_string();
    let consequent_role_literals: Vec<(String, String)> = rule.consequent_role_literals.iter()
        .map(|crl| (crl.role.clone(), crl.value.clone())).collect();
    // task-7: AbsenceOf has been removed. Negation-guarded antecedents
    // no longer exist, so there are never any negation reads.
    let negation_reads: Vec<(String, Vec<(String, String)>)> = Vec::new();
    (consequent_cell, consequent_role_literals, negation_reads)
}

/// task-814-stratify-3plus: convenience helper for synthetic rules
/// (subtype inheritance, SM init/event-fold, CWA negation, …) that
/// know their consequent cell but don't go through a `DerivationRuleDef`.
/// Returns the metadata triple in the same shape as
/// `derivation_dep_metadata` so all `CompiledDerivation` construction
/// sites can share field initialisation.
fn derivation_dep_metadata_synth(consequent_cell: String) -> (
    String,
    Vec<(String, String)>,
    Vec<(String, Vec<(String, String)>)>,
) {
    (consequent_cell, Vec::new(), Vec::new())
}

/// upsert-safe-propagation: compute the cells whose forward-chain keyed
/// writes UPSERT (last-write-wins) instead of conflict-rejecting —
/// replacing the hand-maintained `SM_STATUS_UPSERT_CELLS` allowlist with a
/// value derived from the rule graph.
///
/// `seed` is the consequent cell(s) of the recursive from-guarded SM
/// event-fold: the cell(s) GUARANTEED monotone-advancing, where a same-key
/// "conflict" is a legal advance, not a UC violation. `deps` is
/// `(consequent_cell, antecedent_cells)` for every derivation. A cell is
/// upsert-safe iff it is a seed OR its derivation reads an upsert-safe cell
/// — a monotone PROJECTION of an advancing cell is itself advancing.
/// Computed as the least fixpoint of that rule so a projection chain
/// (fold -> `Resource_is_currently_in_Status` -> `Task_has_Task_Status`)
/// inherits upsert-safety, while a keyed cell with no fold ancestor keeps
/// conflict-reject so a genuine UC clash is still surfaced. This is the
/// oscillation guard the allowlist provided (upsert only where progress is
/// guaranteed), now propagated structurally instead of pinned by name.
pub(crate) fn compute_upsert_safe_cells(
    seed: &[String],
    deps: &[(String, Vec<String>)],
) -> alloc::collections::BTreeSet<String> {
    let mut safe: alloc::collections::BTreeSet<String> = seed.iter().cloned().collect();
    // Least fixpoint: keep absorbing any consequent that reads an
    // already-safe cell until a full pass adds nothing. Each pass adds
    // >=1 cell or terminates, so it converges in <= deps.len() passes.
    loop {
        let mut added = false;
        for (consequent, antecedents) in deps {
            if consequent.is_empty() || safe.contains(consequent) {
                continue;
            }
            if antecedents.iter().any(|a| safe.contains(a)) {
                safe.insert(consequent.clone());
                added = true;
            }
        }
        if !added {
            break;
        }
    }
    safe
}

/// derivation-aggregate-stratify (to-spec: AREST.tex Thm 5 — derivation is the
/// MONOTONE `lfp(F_S, P')`, "the fixed point is the specification, not the
/// execution plan"; §exec — aggregation is the Klug fold `⟨/,f⟩`, a FUNCTION of
/// its source relation). An aggregate's spec value is the fold over its source
/// at the SOURCE's fixpoint — not an intermediate round. The eager round-by-round
/// plan violates that for a min/max over a GROWING recursive source (it emits a
/// transient partial value the monotone chain can't retract → the {2,3} / toll-
/// in-policy bug). Stratified evaluation restores agreement: assign each DERIVED
/// cell a stratum with an AGGREGATE rule strictly ABOVE its derived source, a
/// positive (non-aggregate) edge at the SAME stratum (so positive recursion
/// stays in one stratum). The chain driver runs strata bottom-up, each to LFP,
/// so an aggregate folds its COMPLETED source and its consumers read the spec
/// value — "Knaster-Tarski guarantees the cheaper path agrees with the spec".
///
/// `deps`: one entry per rule — (consequent cell, positive-read cells,
/// is_aggregate). Returns cell -> stratum, or `None` when unstratifiable (an
/// aggregate/negation edge inside a recursive cycle forces an unbounded strict
/// increase) — the caller then falls back to a single (flat) stratum.
pub(crate) fn compute_derivation_strata(
    deps: &[(String, Vec<String>, bool)],
) -> Option<HashMap<String, usize>> {
    // Reads NOT in this set are base cells (stratum 0) — they impose no
    // constraint and never take an aggregate bump.
    let derived: alloc::collections::BTreeSet<&str> =
        deps.iter().map(|(c, _, _)| c.as_str()).collect();
    let mut stratum: HashMap<String, usize> =
        derived.iter().map(|c| (c.to_string(), 0usize)).collect();
    // A stratifiable graph of N derived cells reaches its top stratum (< N) in
    // <= N propagation passes; one full pass with no change means converged.
    // Past that bound the strata keep rising ⇒ a strict-increase cycle.
    for _ in 0..=derived.len() {
        let mut changed = false;
        for (cons, reads, is_agg) in deps {
            let mut req = stratum.get(cons).copied().unwrap_or(0);
            for rc in reads {
                let rc_s = stratum.get(rc).copied().unwrap_or(0);
                let bump = if *is_agg && derived.contains(rc.as_str()) { 1 } else { 0 };
                req = req.max(rc_s + bump);
            }
            if req > stratum.get(cons).copied().unwrap_or(0) {
                stratum.insert(cons.clone(), req);
                changed = true;
            }
        }
        if !changed {
            return Some(stratum);
        }
    }
    None
}

/// A compiled state machine. func is the transition function: <state, event> -> state'.
/// statuses retained for introspection (machine:{noun}:statuses could expose it).
#[allow(dead_code)]
pub(crate) struct CompiledStateMachine {
    pub(crate) noun_name: String,
    pub(crate) statuses: Vec<String>,
    pub(crate) initial: String,
    pub(crate) func: crate::ast::Func,
    pub(crate) transition_table: Vec<(String, String, String)>,
    /// rmap-3nf-tables (iii): the State Machine Definition id this SM
    /// was compiled from (`State_Machine_Definition_is_for_Noun`).
    /// Empty when the noun has no SMD fact (degenerate/test SMs) —
    /// the instance-of-definition backfill skips those.
    pub(crate) definition_id: String,
}

